package com.meteor.memory.core.crypto

import java.security.GeneralSecurityException
import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * AES-256-GCM envelope implementing the frozen [FileCrypto] contract.
 *
 * Wire layout produced by [encrypt]:
 *
 * ```
 * [0]      ivLength  (always 12 today, stored so the format can migrate)
 * [1..12]  iv / nonce, generated by the cipher (never reused)
 * [13..]   ciphertext || GCM tag (128 bit)
 * ```
 *
 * The key is supplied through [keyProvider] rather than held, so this class is
 * pure JVM logic and unit-testable with a plain [javax.crypto.spec.SecretKeySpec].
 * Production wires it to [KeystoreKeyStore].
 */
class AesGcmFileCrypto(
    private val keyProvider: () -> SecretKey,
) : FileCrypto {

    override fun encrypt(plaintext: ByteArray): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        // No IvParameterSpec: the cipher generates a fresh random nonce, and the
        // Keystore refuses keys that would allow nonce reuse.
        cipher.init(Cipher.ENCRYPT_MODE, keyProvider())
        val iv = cipher.iv
        require(iv.size <= 255) { "unexpected IV length ${iv.size}" }
        val payload = cipher.doFinal(plaintext)

        return ByteArray(1 + iv.size + payload.size).also { out ->
            out[0] = iv.size.toByte()
            iv.copyInto(out, destinationOffset = 1)
            payload.copyInto(out, destinationOffset = 1 + iv.size)
        }
    }

    override fun decrypt(ciphertext: ByteArray): ByteArray {
        require(ciphertext.size > 1 + TAG_BITS / 8) { "ciphertext too short" }

        val ivLength = ciphertext[0].toInt() and 0xFF
        require(ivLength in 12..16 && ciphertext.size > 1 + ivLength) { "invalid IV length $ivLength" }

        val iv = ciphertext.copyOfRange(1, 1 + ivLength)
        val payload = ciphertext.copyOfRange(1 + ivLength, ciphertext.size)

        val cipher = Cipher.getInstance(TRANSFORMATION)
        return try {
            cipher.init(Cipher.DECRYPT_MODE, keyProvider(), GCMParameterSpec(TAG_BITS, iv))
            cipher.doFinal(payload)
        } catch (e: GeneralSecurityException) {
            // Wrong key, tampered bytes, or truncated file. Never leak partial data.
            throw CryptoException("decryption failed", e)
        }
    }

    private companion object {
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val TAG_BITS = 128
    }
}

/** Raised for any decryption failure so callers can surface a clean error. */
class CryptoException(message: String, cause: Throwable? = null) : Exception(message, cause)

/** Production factory: Keystore-backed, key generated on first use. */
fun androidKeystoreFileCrypto(alias: String = KeystoreKeyStore.DEFAULT_ALIAS): FileCrypto {
    val keyStore = KeystoreKeyStore()
    return AesGcmFileCrypto { keyStore.secretKey(alias) }
}
